        // The Roles.Role struct is a mapping, which is stored at keccak256(key . slot)
        // We need to set _whitelistAdmins.bearer[ourAddress] = true
        bytes32 whitelistAdminSlot = bytes32(uint256(51)); // Base slot for _whitelistAdmins
        // For mapping, the value is at keccak256(ourAddress . whitelistAdminSlot)
