        deal(TARGET, other, 1000 * 10**18);

        // Get pair address to avoid transferring from it
        address pair = Plenty(TARGET).uniswapV2Pair();
        console.log("Pair address:", pair);

        // Make transfer from other (not pair) to trigger swap
        vm.prank(other);
        Plenty(TARGET).transfer(address(0x456), 1 * 10**18);

        console.log("Transfer made to trigger swap");

        // Check if swap happened by comparing contract balance
        uint256 newContractBalance = Plenty(TARGET).balanceOf(TARGET);
        console.log("Contract balance after swap trigger:", newContractBalance);

