        Plenty(TARGET).transfer(address(0x789), 1 * 10**18);

        uint256 ourTokenBalanceAfter = Plenty(TARGET).balanceOf(address(this));
        console.log("Our token balance before/after:", ourTokenBalanceBefore, ourTokenBalanceAfter);

